//! End-to-end tests for exact integers and arithmetic (certificate v11).
//!
//! A certificate is generated by one CLI process and checked by a second
//! process that only runs `:load` and `:verify-cert`, so the arithmetic step is
//! exercised on the exported JSON, not on the reasoner's in-memory derivation.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::atomic::{AtomicU64, Ordering};

use std_deduce_cert::Certificate;

const PROVED: i32 = 0;
const GAP: i32 = 1;
const ERROR: i32 = 2;

fn examples_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples")
}

fn example(name: &str) -> PathBuf {
    let path = examples_dir().join(name);
    assert!(path.is_file(), "missing example file: {}", path.display());
    path
}

fn run(commands: Vec<String>) -> Output {
    Command::new(env!("CARGO_BIN_EXE_std-deduce"))
        .args(commands)
        .output()
        .unwrap_or_else(|e| panic!("failed to run the CLI: {e}"))
}

fn session(name: &str, commands: &[String]) -> Output {
    let mut all = vec![format!(":load {}", example(name).display())];
    all.extend_from_slice(commands);
    run(all)
}

fn stdout(output: &Output) -> String {
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn stderr(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

fn assert_exit(output: &Output, expected: i32) {
    let code = output.status.code();
    assert_eq!(
        code,
        Some(expected),
        "expected exit {expected}, got {code:?}\nstdout:\n{}\nstderr:\n{}",
        stdout(output),
        stderr(output)
    );
}

/// `:load` prints its report before `:cert`, so the certificate is the tail
/// starting at the first `{`.
fn certificate_json(output: &Output) -> Certificate {
    let text = stdout(output);
    let start = text
        .find('{')
        .unwrap_or_else(|| panic!("no certificate JSON in stdout:\n{text}"));
    Certificate::from_json(text[start..].trim_end())
        .unwrap_or_else(|e| panic!("invalid certificate JSON:\n{e}\nstdout:\n{text}"))
}

fn certificate_text(output: &Output) -> String {
    let text = stdout(output);
    let start = text
        .find('{')
        .unwrap_or_else(|| panic!("no certificate JSON in stdout:\n{text}"));
    text[start..].trim_end().to_owned()
}

fn temp_path(tag: &str, extension: &str) -> PathBuf {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let n = NEXT.fetch_add(1, Ordering::Relaxed);
    std::env::temp_dir().join(format!(
        "std-deduce-arithmetic-{}-{tag}-{n}.{extension}",
        std::process::id()
    ))
}

/// A file removed when the test ends (including on panic).
struct TempFile {
    path: PathBuf,
}

impl TempFile {
    fn new(tag: &str, extension: &str, contents: &str) -> Self {
        let path = temp_path(tag, extension);
        fs::write(&path, contents).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
        TempFile { path }
    }

    fn path_text(&self) -> String {
        self.path.display().to_string()
    }
}

impl Drop for TempFile {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

/// A CLI session that loads a temporary theory, then runs the given commands.
fn session_with(file: &TempFile, commands: &[String]) -> Output {
    let mut all = vec![format!(":load {}", file.path_text())];
    all.extend_from_slice(commands);
    run(all)
}

#[test]
fn the_example_shows_the_computation_step() {
    let output = session("赔偿合计.std", &[":why 合计 甲 5000".into()]);
    assert_exit(&output, PROVED);
    let stdout = stdout(&output);
    assert!(
        stdout.contains("计算：合计 甲 (add 3000 2000) = 合计 甲 5000"),
        "{stdout}"
    );
    assert!(
        stdout.contains("实例：p ↦ 甲，a ↦ 3000，b ↦ 2000"),
        "{stdout}"
    );
    assert!(stdout.contains("推导已通过独立校验。"), "{stdout}");
    assert!(!stdout.contains("合计 甲 (add 3000 2000)  ⟨"), "{stdout}");
}

#[test]
fn the_certificate_is_v11_and_records_the_computed_step() {
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    assert_exit(&output, PROVED);
    let certificate = certificate_json(&output);
    assert_eq!(certificate.format_version.get(), 11);
    let text = certificate_text(&output);
    assert!(
        text.contains("\"kind\": \"num\""),
        "a literal is a number node: {text}"
    );
    // The recorded conclusion is the value; the `computed` field is the rule's
    // own conclusion under the bindings.
    let node = certificate
        .nodes
        .iter()
        .find_map(|node| match node {
            std_deduce_cert::Node::RuleApplication {
                rule,
                conclusion,
                computed,
                ..
            } => Some((rule, conclusion, computed)),
            _ => None,
        })
        .expect("the rule step is recorded");
    assert_eq!(node.0, "赔偿合计");
    assert_eq!(
        node.1,
        &std_deduce_cert::CertExpr::App {
            func: Box::new(std_deduce_cert::CertExpr::App {
                func: Box::new(std_deduce_cert::CertExpr::Const {
                    name: "合计".into()
                }),
                arg: Box::new(std_deduce_cert::CertExpr::Const { name: "甲".into() }),
            }),
            arg: Box::new(std_deduce_cert::CertExpr::Num { value: 5000 }),
        }
    );
    let computed = node.2.as_ref().expect("the arithmetic step is recorded");
    assert_eq!(
        computed,
        &std_deduce_cert::CertExpr::App {
            func: Box::new(std_deduce_cert::CertExpr::App {
                func: Box::new(std_deduce_cert::CertExpr::Const {
                    name: "合计".into()
                }),
                arg: Box::new(std_deduce_cert::CertExpr::Const { name: "甲".into() }),
            }),
            arg: Box::new(std_deduce_cert::CertExpr::App {
                func: Box::new(std_deduce_cert::CertExpr::App {
                    func: Box::new(std_deduce_cert::CertExpr::Const { name: "add".into() }),
                    arg: Box::new(std_deduce_cert::CertExpr::Num { value: 3000 }),
                }),
                arg: Box::new(std_deduce_cert::CertExpr::Num { value: 2000 }),
            }),
        }
    );
}

#[test]
fn a_generated_certificate_verifies_in_a_fresh_session() {
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    assert_exit(&output, PROVED);
    let json = certificate_text(&output);
    let file = TempFile::new("generated", "json", &json);
    let verify = session(
        "赔偿合计.std",
        &[format!(":verify-cert {}", file.path_text())],
    );
    assert_exit(&verify, PROVED);
    let stdout = stdout(&verify);
    assert!(stdout.contains("逻辑校验：通过"), "{stdout}");
    assert!(stdout.contains("内核证明：通过"), "{stdout}");
    assert!(
        stdout.contains("目标绑定") || stdout.contains("根已证明"),
        "{stdout}"
    );
}

#[test]
fn a_tampered_number_is_rejected_and_the_node_is_named() {
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    let json = certificate_text(&output);
    let tampered = json.replace("\"value\": 5000", "\"value\": 9000");
    assert_ne!(
        tampered, json,
        "the fixture must contain the computed total"
    );
    let file = TempFile::new("tampered-number", "json", &tampered);
    let verify = session(
        "赔偿合计.std",
        &[format!(":verify-cert {}", file.path_text())],
    );
    assert_exit(&verify, ERROR);
    let stdout = stdout(&verify);
    assert!(stdout.contains("逻辑校验：失败"), "{stdout}");
    assert!(
        stdout.contains("节点 2"),
        "the step's node must be named: {stdout}"
    );
    assert!(stdout.contains("9000"), "{stdout}");
    assert!(stdout.contains("add 3000 2000"), "{stdout}");
}

#[test]
fn a_swapped_operation_is_rejected() {
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    let json = certificate_text(&output);
    let tampered = json.replace("\"name\": \"add\"", "\"name\": \"mul\"");
    assert_ne!(tampered, json, "the computed step must mention `add`");
    let file = TempFile::new("tampered-operation", "json", &tampered);
    let verify = session(
        "赔偿合计.std",
        &[format!(":verify-cert {}", file.path_text())],
    );
    assert_exit(&verify, ERROR);
    let stdout = stdout(&verify);
    assert!(
        stdout.contains("算术步骤与规则不一致"),
        "the arithmetic step must be named: {stdout}"
    );
    assert!(stdout.contains("mul 3000 2000"), "{stdout}");
}

#[test]
fn a_tampered_binding_is_rejected() {
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    let json = certificate_text(&output);
    // Change the parameter binding `a` only: the premise still proves
    // `医疗费 甲 3000`, so the instance no longer matches its own premises.
    let bindings_at = json.find("\"bindings\"").expect("bindings are recorded");
    let tail = json[bindings_at..].replace("\"value\": 3000", "\"value\": 4000");
    let tampered = format!("{}{}", &json[..bindings_at], tail);
    let file = TempFile::new("tampered-binding", "json", &tampered);
    let verify = session(
        "赔偿合计.std",
        &[format!(":verify-cert {}", file.path_text())],
    );
    assert_exit(&verify, ERROR);
    let stdout = stdout(&verify);
    assert!(
        stdout.contains("节点 2"),
        "the step's node must be named: {stdout}"
    );
    assert!(
        stdout.contains("医疗费 甲 3000") || stdout.contains("医疗费 甲 4000"),
        "the premise mismatch must be named: {stdout}"
    );
}

#[test]
fn a_version_nine_certificate_is_rejected() {
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    let json = certificate_text(&output);
    let old = json.replace("\"format_version\": 11", "\"format_version\": 9");
    assert_ne!(old, json, "the fixture must record the version");
    let file = TempFile::new("version-nine", "json", &old);
    let verify = session(
        "赔偿合计.std",
        &[format!(":verify-cert {}", file.path_text())],
    );
    assert_exit(&verify, ERROR);
    assert!(
        stderr(&verify).contains("supports 11"),
        "{}",
        stderr(&verify)
    );
}

#[test]
fn a_removed_computed_form_is_rejected() {
    // A step whose instance really computes something must carry the
    // pre-evaluation form. Deleting it from the exported JSON would leave the
    // total as the only trace of the computation, so the checker refuses the
    // step and names the node.
    let output = session("赔偿合计.std", &[":cert 合计 甲 5000".into()]);
    let json = certificate_text(&output);
    let mut value: serde_json::Value =
        serde_json::from_str(&json).expect("the certificate is JSON");
    let nodes = value["nodes"].as_array_mut().expect("nodes is an array");
    let step = nodes
        .iter_mut()
        .find(|node| node["kind"] == "rule_application")
        .expect("the rule step is recorded");
    assert!(
        step["computed"].is_object(),
        "the generated step records the arithmetic"
    );
    step.as_object_mut()
        .expect("a node is an object")
        .remove("computed");
    let text = serde_json::to_string_pretty(&value).expect("the edited certificate serializes");
    let file = TempFile::new("missing-computed", "json", &text);
    let verify = session(
        "赔偿合计.std",
        &[format!(":verify-cert {}", file.path_text())],
    );
    assert_exit(&verify, ERROR);
    let stdout = stdout(&verify);
    assert!(
        stdout.contains("节点 2"),
        "the step's node must be named: {stdout}"
    );
    assert!(
        stdout.contains("没有记录未求值形式"),
        "the missing arithmetic record must be named: {stdout}"
    );
}

#[test]
fn amounts_are_integer_cents_and_never_yuan() {
    // The example states its unit convention: every amount is an exact integer
    // number of 「分」, and the total is the sum of those cents.
    let source = fs::read_to_string(example("赔偿合计.std")).expect("the example is readable");
    assert!(
        source.contains("金额一律用整数「分」"),
        "the example must state the unit: {source}"
    );
    assert!(
        source.contains("医疗费 3000 分 + 误工费 2000 分 = 合计 5000 分"),
        "the example must state the sum in 分: {source}"
    );
    assert!(
        !source.contains('元'),
        "the example must not talk about 元: {source}"
    );

    let output = session("赔偿合计.std", &[":why 合计 甲 5000".into()]);
    assert_exit(&output, PROVED);
    let stdout = stdout(&output);
    assert!(
        stdout.contains("计算：合计 甲 (add 3000 2000) = 合计 甲 5000"),
        "the computed total is stated in cents: {stdout}"
    );
    assert!(
        !stdout.contains('元'),
        "the output must not convert cents to 元: {stdout}"
    );
}

#[test]
fn the_conflict_example_defeats_the_computed_total() {
    // The verified amount is 9000; the rule computes 5000. `unique 合计 2`
    // makes the two values a conflict, and the strict fact wins.
    let wrong = session("金额算错-合计冲突.std", &[":why 合计 甲 5000".into()]);
    assert_exit(&wrong, GAP);
    let wrong_stdout = stdout(&wrong);
    assert!(wrong_stdout.contains("冲突已裁决"), "{wrong_stdout}");
    assert!(
        wrong_stdout.contains("本结论「合计 甲 5000」被否决"),
        "{wrong_stdout}"
    );
    assert!(
        wrong_stdout.contains("严格事实优先于可废止规则结论"),
        "{wrong_stdout}"
    );
    assert!(
        wrong_stdout.contains("计算：合计 甲 (add 3000 2000) = 合计 甲 5000"),
        "{wrong_stdout}"
    );

    let winner = session("金额算错-合计冲突.std", &[":why 合计 甲 9000".into()]);
    assert_exit(&winner, PROVED);
    assert!(
        stdout(&winner).contains("冲突（已裁决）：合计 甲 5000 与 合计 甲 9000"),
        "{}",
        stdout(&winner)
    );
}

#[test]
fn a_chain_of_two_sums_computes_each_step() {
    let file = TempFile::new("chain", "std", CHAIN_THEORY);
    let output = session_with(&file, &[":why 合计 甲 5500".into()]);
    assert_exit(&output, PROVED);
    let stdout = stdout(&output);
    assert!(
        stdout.contains("计算：小计 甲 (add 3000 2000) = 小计 甲 5000"),
        "{stdout}"
    );
    assert!(
        stdout.contains("计算：合计 甲 (add 5000 500) = 合计 甲 5500"),
        "{stdout}"
    );
}

#[test]
fn the_same_rule_computes_different_totals_for_different_facts() {
    let file = TempFile::new("instances", "std", CHAIN_THEORY);
    let first = session_with(&file, &[":why 合计 甲 5500".into()]);
    assert_exit(&first, PROVED);
    let second = session_with(&file, &[":why 合计 乙 330".into()]);
    assert_exit(&second, PROVED);
    assert!(
        stdout(&second).contains("计算：合计 乙 (add 300 30) = 合计 乙 330"),
        "{}",
        stdout(&second)
    );
    // The two instances are different bindings of the same rule, and each
    // conclusion appears on its own.
    assert!(
        !stdout(&second).contains("合计 甲 5500"),
        "the other instance must not be claimed: {}",
        stdout(&second)
    );
}

#[test]
fn an_overflowing_total_is_an_error() {
    let file = TempFile::new("overflow", "std", OVERFLOW_THEORY);
    let output = session_with(&file, &[":why 合计 甲 1".into()]);
    assert_exit(&output, ERROR);
    let text = format!("{}{}", stdout(&output), stderr(&output));
    assert!(text.contains("整数运算溢出"), "{text}");
    assert!(text.contains("9223372036854775807"), "{text}");
}

#[test]
fn a_literal_out_of_range_is_rejected_at_its_position() {
    let file = TempFile::new(
        "literal-overflow",
        "std",
        "sort 人\n#check 9223372036854775808\n",
    );
    // The file entry point reports a load failure with exit `1`, like any other
    // malformed theory.
    let output = run(vec![file.path_text()]);
    assert_exit(&output, GAP);
    let text = format!("{}{}", stdout(&output), stderr(&output));
    assert!(
        text.contains(":2:8:"),
        "the position must be reported: {text}"
    );
    assert!(text.contains("超出 i64 范围"), "{text}");
}

#[test]
fn negation_comparisons_and_arithmetic_type_check() {
    let file = TempFile::new(
        "types",
        "std",
        "sort 人\nobj 甲 : 人\n#check (3000 + 2000)\n#check -3000\n#check ((3000 * -2) + 1)\n#proposition (less 3000 5000)\n#proposition (le 5000 5000)\n",
    );
    let output = session_with(&file, &[]);
    assert_exit(&output, PROVED);
    let stdout = stdout(&output);
    assert!(stdout.contains("✓ add 3000 2000 : Int"), "{stdout}");
    assert!(stdout.contains("✓ -3000 : Int"), "{stdout}");
    assert!(stdout.contains("✓ add (mul 3000 -2) 1 : Int"), "{stdout}");
    assert!(stdout.contains("命题：less 3000 5000"), "{stdout}");
}

#[test]
fn an_operand_of_the_wrong_type_is_refused() {
    let file = TempFile::new(
        "wrong-operand",
        "std",
        "sort 人\nobj 甲 : 人\n#check (3000 + 甲)\n",
    );
    let output = run(vec![file.path_text()]);
    assert_exit(&output, GAP);
    let text = format!("{}{}", stdout(&output), stderr(&output));
    assert!(text.contains("类型不匹配"), "{text}");
}

#[test]
fn a_json_case_with_integer_amounts_still_loads() {
    // The JSON entry point elaborates propositions with the same parser, so
    // integer literals work there too, and the rule computes the total.
    let case = TempFile::new(
        "case",
        "json",
        r#"{
  "schema_version": 1,
  "case": "乙的赔偿合计",
  "imports": [],
  "objects": [
    { "name": "乙", "type": "人" }
  ],
  "facts": [
    {
      "proposition": "医疗费 乙 100",
      "identity": "user_asserted",
      "source": { "text": "示例卷宗", "locator": "乙医疗费" }
    },
    {
      "proposition": "误工费 乙 200",
      "identity": "user_asserted",
      "source": { "text": "示例卷宗", "locator": "乙误工费" }
    }
  ],
  "goals": ["合计 乙 300"]
}"#,
    );
    let theory = TempFile::new("case-theory", "std", SUM_THEORY);
    let output = run(vec![
        format!(":load {}", theory.path_text()),
        format!(":load-case {}", case.path_text()),
        ":why 合计 乙 300".into(),
    ]);
    assert_exit(&output, PROVED);
    let stdout = stdout(&output);
    assert!(
        stdout.contains("计算：合计 乙 (add 100 200) = 合计 乙 300"),
        "{stdout}"
    );
}

/// A sum rule over two amounts, plus a second rule that adds a third amount to
/// the first rule's total.
const CHAIN_THEORY: &str = r#"
sort 人
def 金额 : Type := Int
pred 医疗费 : 人 → 金额 → Prop
pred 误工费 : 人 → 金额 → Prop
pred 护理费 : 人 → 金额 → Prop
pred 小计 : 人 → 金额 → Prop
pred 合计 : 人 → 金额 → Prop
obj 甲 : 人
obj 乙 : 人
axiom 甲医疗 : 医疗费 甲 3000
  identity verified
  source text "卷" locator "甲医疗"
axiom 甲误工 : 误工费 甲 2000
  identity verified
  source text "卷" locator "甲误工"
axiom 甲护理 : 护理费 甲 500
  identity verified
  source text "卷" locator "甲护理"
axiom 乙医疗 : 医疗费 乙 100
  identity verified
  source text "卷" locator "乙医疗"
axiom 乙误工 : 误工费 乙 200
  identity verified
  source text "卷" locator "乙误工"
axiom 乙护理 : 护理费 乙 30
  identity verified
  source text "卷" locator "乙护理"
rule 小计规则 :
  params p : 人, a : 金额, b : 金额
  premise 医疗费 p a
  premise 误工费 p b
  conclude 小计 p (a + b)
  source text "法" locator "一"
rule 合计规则 :
  params p : 人, c : 金额, d : 金额
  premise 小计 p c
  premise 护理费 p d
  conclude 合计 p (c + d)
  source text "法" locator "二"
"#;

/// The sum rule with a verified fact whose amount overflows when added to 1.
const OVERFLOW_THEORY: &str = r#"
sort 人
def 金额 : Type := Int
pred 医疗费 : 人 → 金额 → Prop
pred 误工费 : 人 → 金额 → Prop
pred 合计 : 人 → 金额 → Prop
obj 甲 : 人
axiom 甲医疗 : 医疗费 甲 9223372036854775807
  identity verified
  source text "卷" locator "甲医疗"
axiom 甲误工 : 误工费 甲 1
  identity verified
  source text "卷" locator "甲误工"
rule 赔偿合计 :
  params p : 人, a : 金额, b : 金额
  premise 医疗费 p a
  premise 误工费 p b
  conclude 合计 p (a + b)
  source text "法" locator "一"
"#;

/// Only the declarations the JSON case test needs: the case supplies the facts
/// and the individual.
const SUM_THEORY: &str = r#"
sort 人
def 金额 : Type := Int
pred 医疗费 : 人 → 金额 → Prop
pred 误工费 : 人 → 金额 → Prop
pred 合计 : 人 → 金额 → Prop
rule 赔偿合计 :
  params p : 人, a : 金额, b : 金额
  premise 医疗费 p a
  premise 误工费 p b
  conclude 合计 p (a + b)
  source text "法" locator "一"
"#;
